package es.vargontoc.storyteller.application.service;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.util.List;
import org.junit.jupiter.api.Test;
import es.vargontoc.storyteller.application.ports.out.external.CharacterAgent;
import es.vargontoc.storyteller.application.ports.out.persistence.CatalogCharacterRepository;
import es.vargontoc.storyteller.domain.command.CatalogCharacterCreateCommand;
import es.vargontoc.storyteller.domain.response.CatalogCharacterAgentResult;
import es.vargontoc.storyteller.shared.exceptions.AppException;
import es.vargontoc.storyteller.infrastructure.validations.CatalogCharacterAgentResultValidator;
class CharacterCatalogServiceTest { private final CatalogCharacterAgentResultValidator validator=new CatalogCharacterAgentResultValidator();
 @Test void acceptedAutomaticResultIsPersisted(){ CharacterAgent a=mock(CharacterAgent.class); CatalogCharacterRepository r=mock(CatalogCharacterRepository.class); when(a.generateAutomatically()).thenReturn(ok()); new CharacterCatalogService(a,r,validator,id -> false, java.util.Optional.empty(),mock(PortraitLockService.class),new GenerationGate()).create(new CatalogCharacterCreateCommand(null)); verify(r).create(any()); }
 @Test void acceptedManualResultIsPersisted(){ CharacterAgent a=mock(CharacterAgent.class); CatalogCharacterRepository r=mock(CatalogCharacterRepository.class); when(a.generateFromHint("zorra")).thenReturn(ok()); new CharacterCatalogService(a,r,validator,id -> false, java.util.Optional.empty(),mock(PortraitLockService.class),new GenerationGate()).create(new CatalogCharacterCreateCommand("zorra")); verify(r).create(any()); }
 @Test void rejectedResultIsNotPersisted(){ CharacterAgent a=mock(CharacterAgent.class); CatalogCharacterRepository r=mock(CatalogCharacterRepository.class); when(a.generateAutomatically()).thenReturn(new CatalogCharacterAgentResult(false,"no apto",null,null,null,null,null)); var out=new CharacterCatalogService(a,r,validator,id -> false, java.util.Optional.empty(),mock(PortraitLockService.class),new GenerationGate()).create(new CatalogCharacterCreateCommand(null)); assertFalse(out.accepted()); verifyNoInteractions(r); }
 @Test void incompleteAcceptedResultIsNotPersisted(){ CharacterAgent a=mock(CharacterAgent.class); CatalogCharacterRepository r=mock(CatalogCharacterRepository.class); when(a.generateAutomatically()).thenReturn(new CatalogCharacterAgentResult(true,null,"Luna",null,"zorra",null,List.of())); assertThrows(AppException.class,()->new CharacterCatalogService(a,r,validator,id -> false, java.util.Optional.empty(),mock(PortraitLockService.class),new GenerationGate()).create(new CatalogCharacterCreateCommand(null))); verifyNoInteractions(r); }
 private CatalogCharacterAgentResult ok(){return new CatalogCharacterAgentResult(true,null,"Luna","curiosa","zorra","small orange fox",List.of("small orange fox"));}
 private static final es.vargontoc.storyteller.application.ports.out.GenerationGatePort.GenerationType WRITER=es.vargontoc.storyteller.application.ports.out.GenerationGatePort.GenerationType.WRITER;
 @Test void busyGateRejectsCreateWithoutCallingAgentNorCreating(){ CharacterAgent a=mock(CharacterAgent.class); CatalogCharacterRepository r=mock(CatalogCharacterRepository.class); var gate=new GenerationGate(); gate.tryAcquire(WRITER,1L); var ex=assertThrows(AppException.class,()->new CharacterCatalogService(a,r,validator,id -> false, java.util.Optional.empty(),mock(PortraitLockService.class),gate).create(new CatalogCharacterCreateCommand(null))); assertEquals(org.springframework.http.HttpStatus.CONFLICT,ex.getStatus()); verifyNoInteractions(a,r); assertTrue(gate.isGeneratingStory(1L)); }
 @Test void createReleasesGateOnSuccessAndAgentFailure(){ CharacterAgent a=mock(CharacterAgent.class); CatalogCharacterRepository r=mock(CatalogCharacterRepository.class); var gate=new GenerationGate(); var s=new CharacterCatalogService(a,r,validator,id -> false, java.util.Optional.empty(),mock(PortraitLockService.class),gate);
  when(a.generateAutomatically()).thenReturn(ok()); s.create(new CatalogCharacterCreateCommand(null)); assertTrue(gate.tryAcquire(WRITER,null)); gate.release();
  when(a.generateAutomatically()).thenThrow(new IllegalStateException("ollama")); assertThrows(IllegalStateException.class,()->s.create(new CatalogCharacterCreateCommand(null))); assertTrue(gate.tryAcquire(WRITER,null)); }
 @Test void busyGateRejectsPortraitsWithoutCreatingJob(){ CatalogCharacterRepository r=mock(CatalogCharacterRepository.class); var generation=mock(es.vargontoc.storyteller.application.ports.in.character.PortraitGenerationUseCase.class); var gate=new GenerationGate(); gate.tryAcquire(WRITER,null); var ex=assertThrows(AppException.class,()->portraitsService(r,generation,gate).generatePortraits(7L)); assertEquals(org.springframework.http.HttpStatus.CONFLICT,ex.getStatus()); verifyNoInteractions(generation); }
 @Test void acceptedPortraitsRequestLeavesGateBusyForTheAsyncService(){ CatalogCharacterRepository r=mock(CatalogCharacterRepository.class); var generation=mock(es.vargontoc.storyteller.application.ports.in.character.PortraitGenerationUseCase.class); var gate=new GenerationGate(); portraitsService(r,generation,gate).generatePortraits(7L); verify(generation).generate(7L); assertFalse(gate.tryAcquire(WRITER,null)); }
 @Test void portraitsStartFailureReleasesGate(){ CatalogCharacterRepository r=mock(CatalogCharacterRepository.class); var generation=mock(es.vargontoc.storyteller.application.ports.in.character.PortraitGenerationUseCase.class); doThrow(new IllegalStateException("job en curso")).when(generation).generate(7L); var gate=new GenerationGate(); assertThrows(IllegalStateException.class,()->portraitsService(r,generation,gate).generatePortraits(7L)); assertTrue(gate.tryAcquire(WRITER,null)); }
 private CharacterCatalogService portraitsService(CatalogCharacterRepository r,es.vargontoc.storyteller.application.ports.in.character.PortraitGenerationUseCase generation,GenerationGate gate){return new CharacterCatalogService(mock(CharacterAgent.class),r,validator,id -> false,java.util.Optional.empty(),mock(PortraitLockService.class),gate,generation,mock(es.vargontoc.storyteller.application.ports.in.character.PortraitSelectionUseCase.class),mock(es.vargontoc.storyteller.application.ports.out.persistence.PortraitCandidateStore.class),mock(es.vargontoc.storyteller.application.ports.out.ResourceStorage.class));}
}
